# Agirlikli karar matrisi. Tum puanlar ve agirliklar SENARYO degeridir.
olcutler = [
    ("ogrenme firsati", 0.30),
    ("takim ve mentorluk", 0.25),
    ("toplam nakit paket", 0.20),
    ("calisma duzeni", 0.15),
    ("ilerleme yolu", 0.10),
]
puanlar = {
    "A": [4, 5, 2, 3, 4],
    "B": [3, 2, 5, 5, 3],
}


def agirlikli_puan(olcutler, puan):
    toplam = 0.0
    for (_, w), p in zip(olcutler, puan):
        toplam += w * p
    return round(toplam, 4)


def dogrula(olcutler):
    return round(sum(w for _, w in olcutler), 4) == 1.0


print("agirlik toplami 1 mi:", dogrula(olcutler))
sonuc = {ad: agirlikli_puan(olcutler, p) for ad, p in sorted(puanlar.items())}
for ad in sorted(sonuc, key=lambda a: -sonuc[a]):
    print("{}: {}".format(ad, sonuc[ad]))
print("fark:", round(max(sonuc.values()) - min(sonuc.values()), 4))
